local CannonMaker = {}
local PRODUCTS = {
    hand_culverin = { name = "Ročna kulverina", ironCost = 3, woodCost = 2, gunpowderCost = 1, time = 6, cost = 350, attack = 50, range = 200, durability = 35, description = "Ročna kulverina za pehoto." },
    small_bronze_cannon = { name = "Majhen bronast top", bronzeCost = 4, woodCost = 3, ironCost = 2, gunpowderCost = 2, time = 9, cost = 800, attack = 75, range = 250, durability = 50, prestige = 3, description = "Majhen bronast top za utrdbe." },
    iron_cannon = { name = "Železen top", ironCost = 6, woodCost = 4, gunpowderCost = 3, time = 13, cost = 1700, attack = 110, range = 300, durability = 70, prestige = 6, happiness = 1, description = "Železen top za obleganje." },
    heavy_bronze_cannon = { name = "Težki bronast top", bronzeCost = 8, ironCost = 4, woodCost = 5, gunpowderCost = 4, time = 17, cost = 3500, attack = 160, range = 350, durability = 90, prestige = 12, happiness = 2, description = "Težki bronast top za močne napade." },
    silver_decorated_cannon = { name = "Srebrno okrašen top", bronzeCost = 8, ironCost = 4, silverCost = 2, woodCost = 5, gunpowderCost = 4, time = 21, cost = 6800, attack = 220, range = 400, durability = 110, prestige = 22, happiness = 4, description = "Top s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_cannon = { name = "Kraljevski veliki top", bronzeCost = 12, ironCost = 6, steelCost = 4, goldCost = 3, silverCost = 2, woodCost = 8, gunpowderCost = 6, jewelCost = 1, time = 28, cost = 14000, attack = 320, range = 500, durability = 160, prestige = 65, happiness = 13, description = "Veliki kraljevski top z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Toparska delavnica", cost = { gold = 600, wood = 200, stone = 250 }, upkeep = 14, qualityBonus = 5 },
    foundry = { name = "Livarna topov", cost = { gold = 2200, wood = 350, stone = 600, iron = 14, bronze = 10 }, upkeep = 50, qualityBonus = 18 },
    boring_room = { name = "Vrtalnica", cost = { gold = 5000, wood = 500, stone = 900, silver = 60, steel = 10 }, upkeep = 100, qualityBonus = 30 },
    royal_cannon_atelier = { name = "Kraljevski atelje topov", cost = { gold = 20000, wood = 1200, stone = 2000, gold = 300, jewel = 30 }, upkeep = 400, qualityBonus = 55, prestigeBonus = 60 },
}
CannonMaker.ironStock = 14; CannonMaker.bronzeStock = 14; CannonMaker.steelStock = 10; CannonMaker.woodStock = 18; CannonMaker.silverStock = 8; CannonMaker.goldStock = 6; CannonMaker.jewelStock = 6; CannonMaker.gunpowderStock = 12
CannonMaker.productStock = {}; CannonMaker.buildings = {}; CannonMaker.maker = nil; CannonMaker.activeMaking = {}; CannonMaker.totalProducts = 0; CannonMaker.dayTimer = 0
function CannonMaker.init() CannonMaker.ironStock=14; CannonMaker.bronzeStock=14; CannonMaker.steelStock=10; CannonMaker.woodStock=18; CannonMaker.silverStock=8; CannonMaker.goldStock=6; CannonMaker.jewelStock=6; CannonMaker.gunpowderStock=12; CannonMaker.productStock={}; CannonMaker.buildings={}; CannonMaker.maker=nil; CannonMaker.activeMaking={}; CannonMaker.totalProducts=0; CannonMaker.dayTimer=0; print("[CannonMaker] Royal Cannon Maker System initialized (6 products, 4 buildings)") end
function CannonMaker.hireMaker(n,s) s=s or math.random(55,95); local c=750+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CannonMaker.maker={name=n or ("Topar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Topar najet: %s (spretnost: %d)",CannonMaker.maker.name,s),"success") end; return true end
function CannonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CannonMaker.build(id) local ok,e=CannonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CannonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CannonMaker.getQualityBonus() local b=0; for _,bd in ipairs(CannonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CannonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CannonMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CannonMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.steelCost and CannonMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and CannonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and CannonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CannonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CannonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.gunpowderCost and CannonMaker.gunpowderStock<(d.gunpowderCost or 0) then return false,"Premalo smodnika" end; if #CannonMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CannonMaker.maker then return false,"Potreben topar" end; return true end
function CannonMaker.make(pt,qty) qty=qty or 1; local ok,e=CannonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CannonMaker.ironStock=CannonMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CannonMaker.bronzeStock=CannonMaker.bronzeStock-d.bronzeCost*qty end; if d.steelCost then CannonMaker.steelStock=CannonMaker.steelStock-d.steelCost*qty end; if d.woodCost then CannonMaker.woodStock=CannonMaker.woodStock-d.woodCost*qty end; if d.silverCost then CannonMaker.silverStock=CannonMaker.silverStock-d.silverCost*qty end; if d.goldCost then CannonMaker.goldStock=CannonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CannonMaker.jewelStock=CannonMaker.jewelStock-d.jewelCost*qty end; if d.gunpowderCost then CannonMaker.gunpowderStock=CannonMaker.gunpowderStock-d.gunpowderCost*qty end; local t=d.time; if CannonMaker.maker then t=math.max(1,t-math.floor(CannonMaker.maker.skill/12)) end; table.insert(CannonMaker.activeMaking,{id="cannon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CannonMaker.completeMaking(m) local q=1.0+(CannonMaker.getQualityBonus()/100); if CannonMaker.maker then q=q+(CannonMaker.maker.skill/150) end; q=math.min(2.5,q); CannonMaker.productStock[m.productType]=(CannonMaker.productStock[m.productType] or 0)+m.quantity; CannonMaker.totalProducts=CannonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CannonMaker.maker then CannonMaker.maker.itemsMade=CannonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CannonMaker.maker.skill=math.min(100,CannonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Top izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cannon.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function CannonMaker.update(dt) if not _G.state then return end; CannonMaker.dayTimer=CannonMaker.dayTimer+dt; if CannonMaker.dayTimer>=30 then CannonMaker.dayTimer=0; for i=#CannonMaker.activeMaking,1,-1 do local m=CannonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CannonMaker.completeMaking(m); table.remove(CannonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CannonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CannonMaker.maker then tu=tu+25 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CannonMaker.getStats() return {ironStock=CannonMaker.ironStock,bronzeStock=CannonMaker.bronzeStock,steelStock=CannonMaker.steelStock,woodStock=CannonMaker.woodStock,silverStock=CannonMaker.silverStock,goldStock=CannonMaker.goldStock,jewelStock=CannonMaker.jewelStock,gunpowderStock=CannonMaker.gunpowderStock,productStock=CannonMaker.productStock,numBuildings=#CannonMaker.buildings,hasMaker=CannonMaker.maker~=nil,makerName=CannonMaker.maker and CannonMaker.maker.name or "—",makerSkill=CannonMaker.maker and CannonMaker.maker.skill or 0,activeMaking=#CannonMaker.activeMaking,totalProducts=CannonMaker.totalProducts} end
return CannonMaker
